  secoes = EXCLUDED.secoes,
  ativo = true,
  updated_at = NOW();


INSERT INTO public.politica_modelo (id, nome, descricao, cor, ordem, secoes, ativo) VALUES (
  'documento_portal_termo_uso',
  'Termo de Uso (portal / serviço)',
  'Modelo PPSI de Termo de Uso (Guia de Elaboração de Termo de Uso e Política de Privacidade)',
  '#455A64',
  19,
  '[{"id": 0, "secao": "Termo de Uso", "titulo": "Introdução", "descricao": "IMPORTANTE: Modelo simplificado do PPSI (Guia de Elaboração de Termo de Uso e Política de Privacidade). Adeque ao serviço concreto. Trechos exemplificativos e orientações em vermelho devem ser revisados antes da publicação. Não dispensa análise jurídica.", "texto": ""}, {"id": 1, "secao": "Aceitação do Termo de Uso", "titulo": "Contrato de adesão", "descricao": "", "texto": "<p>O presente Termo de Uso se refere a um contrato de adesão firmado entre o usuário e o fornecedor deste serviço, o(a) Nome da Instituição, localizado(a) em Endereço da Instituição.</p><p>O uso deste serviço está condicionado à aceitação / ciência dos termos e das políticas associadas. O usuário deverá ler tais termos e políticas, certificar-se de havê-los entendido, estar consciente de todas as condições estabelecidas no Termo de Uso e se comprometer a cumpri-las.</p><p>Ao utilizar o serviço, o usuário manifesta estar ciente / de acordo com relação ao conteúdo deste Termo de Uso e estará legalmente vinculado a todas as condições aqui previstas.</p><p>Observações:</p><p>Sobre a escolha da utilização dos termos Aceitação ou Ciência consulte a seção 1.1- Aceitação, Concordância ou Ciência do Termo de Uso do Guia de Elaboração de Termo de Uso e Política de Privacidade para serviços públicos.</p>"}, {"id": 2, "secao": "Definições do Termo de Uso", "titulo": "Glossário", "descricao": "", "texto": "<p>Para os fins deste Termo de Uso, são aplicáveis as seguintes definições:</p><p>Agente público:</p><p>Todo aquele que exerce, ainda que transitoriamente ou sem remuneração, por eleição, nomeação, designação, contratação ou qualquer outra forma de investidura ou vínculo, mandato, cargo, emprego ou função nos órgãos e entidades da Administração Pública, direta e indireta.</p><p>Agentes de Estado:</p><p>Inclui órgãos e entidades da Administração pública além dos seus agentes públicos.</p><p>Códigos maliciosos:</p><p>São qualquer programa de computador, ou parte de um programa, construído com a intenção de provocar danos, obter informações não autorizadas ou interromper o funcionamento de sistemas e/ou redes de computadores.</p><p>Sítios e aplicativos:</p><p>Sítios e aplicativos por meio dos quais o usuário acessa os serviços e conteúdos disponibilizados.</p><p>Terceiro:</p><p>Pessoa ou entidade que não participa diretamente em um contrato, em um ato jurídico ou em um negócio, ou que, para além das partes envolvidas, pode ter interesse num processo jurídico.</p><p>Internet:</p><p>Sistema constituído do conjunto de protocolos lógicos, estruturado em escala mundial para uso público e irrestrito, com a finalidade de possibilitar a comunicação de dados entre terminais por meio de diferentes redes.</p><p>Usuários:</p><p>(ou &quot;Usuário&quot;, quando individualmente considerado): Todas as pessoas naturais que utilizarem o serviço (citar o serviço).</p><p>Observações:</p><p>Outros termos podem ser inseridos neste campo, conforme a necessidade do serviço.</p><p>Definições sobre termos técnicos podem ser consultadas no Glossário do GSI.</p>"}, {"id": 3, "secao": "Arcabouço Legal", "titulo": "Normas aplicáveis", "descricao": "", "texto": "<p>O arcabouço legal aplicável ao serviço citar o Nome do Serviço compreende os seguintes atos legislativos e normativos:</p><p>Lei nº 12.965, de 23 de abril de 2014 - Marco Civil da Internet</p><p>Estabelece princípios, garantias, direitos e deveres para o uso da Internet no Brasil.</p><p>Lei nº 12.527, de 18 de novembro de 2011 - Lei de Acesso à Informação</p><p>Regula o acesso a informações previsto na Constituição Federal.</p><p>Lei nº 13.460, de 26 de junho de 2017</p><p>Dispõe sobre participação, proteção e defesa dos direitos do usuário dos serviços públicos da administração pública.</p><p>Lei nº 13.709, de 14 de agosto de 2018</p><p>Dispõe sobre o tratamento de dados pessoais, inclusive nos meios digitais, por pessoa natural ou por pessoa jurídica de direito público ou privado, com o objetivo de proteger os direitos fundamentais de liberdade e de privacidade e o livre desenvolvimento da personalidade da pessoa natural.</p><p>Lei nº 13.444, de 11 de maio de 2017</p><p>Dispõe sobre a Identificação Civil Nacional (ICN).</p><p>Decreto nº 8.777, de 11 de maio de 2016</p><p>Institui a Política de Dados Abertos do Poder Executivo federal.</p><p>Decreto nº 7.724, de 16 de maio de 2012</p><p>Regulamenta a Lei no 12.527, de 18 de novembro de 2011 (Lei de Acesso à Informação), que dispõe sobre o acesso a informações previsto na Constituição.</p><p>Decreto nº 7.845, de 14 de novembro de 2012</p><p>Regulamenta procedimentos para credenciamento de segurança e tratamento de informação classificada em qualquer grau de sigilo, e dispõe sobre o Núcleo de Segurança e Credenciamento.</p><p>Decreto nº 10.046, de 09 de outubro de 2019</p><p>Dispõe sobre a governança no compartilhamento de dados no âmbito da administração pública federal e institui o Cadastro Base do Cidadão e o Comitê Central de Governança de Dados.</p><p>Normas complementares do Gabinete de Segurança da Informação da Presidência (GSI/PR)</p><p>Disciplinam a Gestão de Segurança da Informação e Comunicações na Administração Pública Federal, direta e indireta, e dá outras providências.</p><p>Decreto nº 9.637, de 26 de dezembro de 2018</p><p>Institui a Política Nacional de Segurança da Informação, dispõe sobre a governança da segurança da informação, e altera o Decreto nº 2.295, de 4 de agosto de 1997, que regulamenta o disposto no art. 24, caput, inciso IX, da Lei nº 8.666, de 21 de junho de 1993, e dispõe sobre a dispensa de licitação nos casos que possam comprometer a segurança nacional.</p><p>Lei nº 12.737, de 30 de novembro de 2012</p><p>Dispõe sobre a tipificação criminal de delitos informáticos.</p><p>Observação: Outras leis, decretos, resoluções, instruções normativas, portarias e demais normativos podem ser inseridos nesta seção, conforme a necessidade do serviço. A relação depende dos normativos específicos aplicáveis ao órgão ou entidade e aos serviços prestados.</p>"}, {"id": 4, "secao": "Descrição do Serviço", "titulo": "O que é oferecido", "descricao": "", "texto": "<p>Inserir o Nome do Serviço.</p><p>Inserir o(a) Nome da Instituição responsável pelo serviço.</p><p>Inserir neste campo, de forma explicativa, a descrição do serviço.</p><p>Trazer tópicos relacionados ao seu objetivo, função, finalidade e outras informações importantes para esclarecer do que trata o serviço prestado.</p>"}, {"id": 5, "secao": "Direitos do Usuário", "titulo": "Direitos e deveres", "descricao": "", "texto": "<p>De acordo com a Lei nº 13.460, de 26 de junho de 2017, são direitos básicos do usuário:</p><p>Participação no acompanhamento da prestação e na avaliação dos serviços;</p><p>Obtenção e utilização dos serviços com liberdade de escolha entre os meios oferecidos e sem discriminação;</p><p>Acesso e obtenção de informações relativas à sua pessoa constantes de registros ou bancos de dados, observado o disposto no inciso X do caput do art. 5º da Constituição Federal e na Lei nº 12.527, de 18 de novembro de 2011;</p><p>Proteção de suas informações pessoais, nos termos da Lei nº 12.527, de 18 de novembro de 2011;</p><p>Atuação integrada e sistêmica na expedição de atestados, certidões e documentos comprobatórios de regularidade; e</p><p>Obtenção de informações precisas e de fácil acesso nos locais de prestação do serviço, assim como sua disponibilização na internet, especialmente sobre:</p><p>horário de funcionamento das unidades administrativas;</p><p>serviços prestados pelo órgão ou entidade, sua localização exata e a indicação do setor responsável pelo atendimento ao público;</p><p>acesso ao agente público ou ao órgão encarregado de receber manifestações;</p><p>situação da tramitação dos processos administrativos em que figure como interessado; e</p><p>valor das taxas e tarifas cobradas pela prestação dos serviços, contendo informações para a compreensão exata da extensão do serviço prestado.</p><p>Outros direitos provenientes de outros normativos devem ser inseridos nesta seção, de acordo com a característica do serviço.</p>"}, {"id": 6, "secao": "Responsabilidades do Usuário", "titulo": "Deveres", "descricao": "", "texto": "<p>Quais são as obrigações dos usuários que utilizam o serviço?</p><p>O usuário se responsabiliza pela precisão e pela veracidade dos dados informados e reconhece que a inconsistência deles poderá implicar a impossibilidade de se utilizar o serviço Inserir o Nome do Serviço.</p><p>Durante a utilização do serviço, a fim de resguardar e de proteger os direitos de terceiros, o usuário se compromete a fornecer somente seus dados pessoais, e não os de terceiros.</p><p>O login e senha só poderão ser utilizados pelo usuário cadastrado. Ele se compromete em manter o sigilo da senha, que é pessoal e intransferível, não sendo possível, em qualquer hipótese, a alegação de uso indevido após o ato de compartilhamento.</p><p>O usuário do serviço é responsável pela atualização dos seus dados pessoais e pelas consequências em caso de omissão ou erros nos dados fornecidos.</p><p>O Usuário é responsável pela reparação de todos e quaisquer danos, diretos ou indiretos (inclusive decorrentes de violação de quaisquer direitos de outros usuários; de terceiros, inclusive direitos de propriedade intelectual; de sigilo; e de personalidade), que sejam causados à Administração Pública, a qualquer outro Usuário, ou ainda a qualquer terceiro, inclusive em virtude do descumprimento do disposto nestes Termos de Uso e Política de Privacidade ou de qualquer ato praticado a partir de seu acesso ao serviço.</p><p>O(a) Nome da Instituição não poderá ser responsabilizado pelos seguintes fatos:</p><p>Equipamento infectado ou invadido por atacantes;</p><p>Equipamento avariado no momento do consumo de serviços;</p><p>Proteção do computador;</p><p>Proteção das informações baseadas nos computadores dos usuários;</p><p>Abuso de uso dos computadores dos usuários;</p><p>Monitoração clandestina do computador dos usuários;</p><p>Vulnerabilidades ou instabilidades existentes nos sistemas dos usuários;</p><p>Perímetro inseguro.</p><p>Em nenhuma hipótese, a Administração Pública Federal será responsável pela instalação, no equipamento do Usuário ou de terceiros, de códigos maliciosos (vírus, trojans, malware, worm, bot, backdoor, spyware, rootkit, ou de quaisquer outros que venham a ser criados), em decorrência da navegação na Internet pelo Usuário.</p><p>Responsabilidade da Administração Pública</p><p>Quais são as responsabilidades da Administração Pública com meus dados?</p><p>A Administração Pública se compromete a cumprir todas as legislações inerentes ao uso correto dos dados pessoais do cidadão de forma a preservar a privacidade dos dados utilizados no serviço, bem como a garantir todos os direitos e garantias legais dos titulares dos dados. Ela também se obriga a promover, independentemente de requerimentos, a divulgação em local de fácil acesso, no âmbito de suas competências, de informações de interesse coletivo ou geral por eles produzidas ou custodiadas. É de responsabilidade da Administração Pública implementar controles de segurança para proteção dos dados pessoais dos titulares.</p><p>A Administração Pública poderá, quanto às ordens judiciais de pedido das informações, compartilhar informações necessárias para investigações ou tomar medidas relacionadas a atividades ilegais, suspeitas de fraude ou ameaças potenciais contra pessoas, bens ou sistemas que sustentam o Serviço ou de outra forma necessárias para cumprir com obrigações legais. Caso ocorra, a Administração Pública notificará os titulares dos dados, salvo quando o processo estiver em segredo de justiça.</p>"}]'::jsonb,
  true
)
ON CONFLICT (id) DO UPDATE SET
  nome = EXCLUDED.nome,
  descricao = EXCLUDED.descricao,
  cor = EXCLUDED.cor,
  ordem = EXCLUDED.ordem,
  secoes = EXCLUDED.secoes,
  ativo = true,
  updated_at = NOW();


ALTER TABLE public.programa ADD COLUMN IF NOT EXISTS link_termo_uso text;
COMMENT ON COLUMN public.programa.link_termo_uso IS 'URL externa do termo de uso; se vazio, usa /{slug}/termo-uso';
